=⚠️ *AI Crisis Management Agent Error*

*Workflow:* {{ $workflow.name }}
*Failed Node:* {{ $execution.lastNodeExecuted }}
*Time:* {{ $now.format('MMM D, YYYY – HH:mm') }}
*Execution ID:* {{ $execution.id }}

parameters.jsCode:
const salesRows = $('Get Sales History').all().map(i => i.json);
const inventoryRows = $('Get Inventory Levels').all().map(i => i.json);
const vendorRows = $('Get Vendor Directory').all().map(i => i.json);
const existingPORows = $('Get Existing Purchase Orders').all().map(i => i.json);

const LOOKBACK_DAYS = 30;
const TREND_WINDOW_DAYS = 7;
const PENDING_LOOKBACK_DAYS = 7;
const now = new Date();
const cutoff30 = new Date(now.getTime() - LOOKBACK_DAYS * 24 * 60 * 60 * 1000);
const cutoff7 = new Date(now.getTime() - TREND_WINDOW_DAYS * 24 * 60 * 60 * 1000);
const pendingCutoff = new Date(now.getTime() - PENDING_LOOKBACK_DAYS * 24 * 60 * 60 * 1000);

const demand30BySku = {};
const demand7BySku = {};
for (const row of salesRows) {
  const sku = String(row.SKU || row.sku || '').trim();
  if (!sku) continue;
  const rowDate = new Date(row.Date || row.date);
  if (isNaN(rowDate.getTime())) continue;
  const units = Number(row.UnitsSold || row.unitsSold || row.units_sold || 0);
  if (rowDate >= cutoff30) demand30BySku[sku] = (demand30BySku[sku] || 0) + units;
  if (rowDate >= cutoff7) demand7BySku[sku] = (demand7BySku[sku] || 0) + units;
}

const vendorBySku = {};
for (const v of vendorRows) {
  const sku = String(v.SKU || v.sku || '').trim();
  if (!sku) continue;
  vendorBySku[sku] = {
    supplierName: v.SupplierName || v.supplierName || '',
    supplierEmail: v.SupplierEmail || v.supplierEmail || '',
    moq: Number(v.MOQ || v.moq || 0)
  };
}

const openStatuses = ['Draft', 'Pending Approval', 'Approved'];
const pendingSkus = new Set();
for (const po of existingPORows) {
  const sku = String(po.SKU || po.sku || '').trim();
  const status = String(po.Status || po.status || '').trim();
  const ts = new Date(po.Timestamp || po.timestamp);
  if (sku && openStatuses.includes(status) && !isNaN(ts.getTime()) && ts >= pendingCutoff) {
    pendingSkus.add(sku);
  }
}

const results = [];

for (const inv of inventoryRows) {
  const sku = String(inv.SKU || inv.sku || '').trim();
  if (!sku) continue;

  const productName = inv.ProductName || inv.productName || '';
  const currentStock = Number(inv.CurrentStock || inv.currentStock || 0);
  const leadTimeDays = Number(inv.LeadTimeDays || inv.leadTimeDays || 7);
  const reorderThresholdDays = Number(inv.ReorderThresholdDays || inv.reorderThresholdDays || 7);
  const safetyStock = Number(inv.SafetyStock || inv.safetyStock || 0);
  const unitCost = Number(inv.UnitCost || inv.unitCost || 0);

  const totalUnitsSold30 = demand30BySku[sku] || 0;
  const totalUnitsSold7 = demand7BySku[sku] || 0;
  const avgDailyDemand = totalUnitsSold30 / LOOKBACK_DAYS;
  const avgDailyDemand7 = totalUnitsSold7 / TREND_WINDOW_DAYS;
  const trendUp = avgDailyDemand > 0 && avgDailyDemand7 > avgDailyDemand * 1.2;

  const daysOfStockRemaining = avgDailyDemand > 0
    ? Math.round((currentStock / avgDailyDemand) * 10) / 10
    : null;

  const vendor = vendorBySku[sku] || { supplierName: '', supplierEmail: '', moq: 0 };
  const alreadyPending = pendingSkus.has(sku);

  let severity = 'OK';
  if (!alreadyPending && daysOfStockRemaining !== null) {
    if (daysOfStockRemaining <= 3) severity = 'Critical';
    else if (daysOfStockRemaining <= reorderThresholdDays) severity = 'Warning';
    else if (trendUp && daysOfStockRemaining <= reorderThresholdDays * 1.5) severity = 'Watch';
  }

  let recommendedQty = 0;
  if (severity === 'Critical' || severity === 'Warning') {
    const targetStock = (avgDailyDemand * (leadTimeDays + reorderThresholdDays)) + safetyStock;
    recommendedQty = Math.max(0, Math.ceil(targetStock - currentStock));
    if (vendor.moq > 0 && recommendedQty > 0 && recommendedQty < vendor.moq) {
      recommendedQty = vendor.moq;
    }
  }

  const poId = severity !== 'OK' ? `${sku}-${Date.now()}` : '';

  results.push({
    json: {
      sku,
      productName,
      currentStock,
      avgDailyDemand: Math.round(avgDailyDemand * 100) / 100,
      avgDailyDemand7: Math.round(avgDailyDemand7 * 100) / 100,
      trendUp,
      daysOfStockRemaining,
      leadTimeDays,
      reorderThresholdDays,
      safetyStock,
      unitCost,
      recommendedQty,
      estimatedCost: Math.round(recommendedQty * unitCost * 100) / 100,
      severity,
      alreadyPending,
      poId,
      supplierName: vendor.supplierName,
      supplierEmail: vendor.supplierEmail,
      moq: vendor.moq
    }
  });
}

return results;

