const items = $input.all().map(i => i.json);
const critical = items.filter(i => i.severity === 'Critical');
const warning = items.filter(i => i.severity === 'Warning');
const watch = items.filter(i => i.severity === 'Watch');
const ok = items.filter(i => i.severity === 'OK');

function rows(list) {
  return list.map(i => `<tr><td>${i.sku}</td><td>${i.productName}</td><td>${i.currentStock}</td><td>${i.daysOfStockRemaining ?? '-'}</td><td>${i.recommendedQty}</td><td>${i.estimatedCost}</td></tr>`).join('');
}

const html = `
<h2>📦 InvenOS AI — Daily Inventory Digest</h2>
<p>${critical.length} Critical, ${warning.length} Warning, ${watch.length} Watch, ${ok.length} OK</p>
<h3 style="color:#c0392b">Critical</h3>
<table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>SKU</th><th>Product</th><th>Stock</th><th>Days Left</th><th>Reorder Qty</th><th>Est. Cost</th></tr>${rows(critical)}</table>
<h3 style="color:#e67e22">Warning</h3>
<table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>SKU</th><th>Product</th><th>Stock</th><th>Days Left</th><th>Reorder Qty</th><th>Est. Cost</th></tr>${rows(warning)}</table>
<h3 style="color:#f1c40f">Watch</h3>
<table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>SKU</th><th>Product</th><th>Stock</th><th>Days Left</th><th>Reorder Qty</th><th>Est. Cost</th></tr>${rows(watch)}</table>
`;

return [{ json: { html, criticalCount: critical.length, warningCount: warning.length, watchCount: watch.length } }];

